    int value;
    Node* next;

    Node(int val) : value(val), next(nullptr) {}
};
```

### Step 2: Implement the Queue (Circular)

This example shows how to implement a circular linked list, which is suitable for implementing queues. A queue in this context operates as if it were infinitely large but only stores elements within a fixed size container.

```cpp
class CircularQueue {
public:
    int size;
    Node* head;  // The first node of the queue
    Node* tail;  // The last node of the queue

    CircularQueue(int capacity) : size(capacity), head(nullptr), tail(nullptr) {}

    ~CircularQueue() { clear(); }

    void enqueue(int value) {
        if (!head) {
            head = new Node(value);
            tail = head;
        } else {
            Node* newNode = new Node(value);

            // Connect the old tail to the new node
            tail->next = newNode;
            tail = newNode;

            if (size == 1) {
                head->next = nullptr;  // To make it circular
            }
        }

        ++size;
    }

    bool dequeue() {
        if (!head) return false;

        Node* temp = head;

        // Replace the head node with the next one.
        head = head->next;

        if (head == tail)
            tail = nullptr;  // To make it circular

        --size;
        delete temp;
        return true;
    }

private:
    void clear() {
        while (head) {
            Node* toDelete = head;
            head = head->next;
            delete toDelete;
        }
        size = 0;
    }
};
```

