    id: ID!
    name: String!
    email: String!
}

type QueryType {
    hello(name: String): String
    users: [User]
}

type MutationType {
    createUser(input: UserInput!): User
}
```

### Step 4: Create the GraphQL Playground

To use a playground where you can write and execute queries, mutations, and subscriptions, add this line to your `server.js` file:

```javascript
const { graphql } = require('graphql');
const { buildSchema } = require('graphql');

// Load your schema from 'schema.graphql'
const typeDefs = require('./schema.graphql');
const resolvers = require('./resolvers'); // Replace with the path to your resolvers

const schema = buildSchema(typeDefs);

const db = {};  // A simple in-memory database example
db.users = [
    { id: "1", name: "Alice", email: "alice@example.com" },
    { id: "2", name: "Bob", email: "bob@example.com" }
];

// This resolver will be called for queries that do not match the schema
const resolvers = {
    QueryType: {
        hello: (root, args) => `Hello ${args.name}!`,
        users: () => db.users,
    },
};

const app = express();
app.use('/graphql', apolloServer.createApolloServer({
    typeDefs,
    resolvers,
}));

// Start your server
const port = 4000;
app.listen(port, () => {
    console.log(`Listening on http://localhost:${port}`);
});
```

### Step 5: Set Up the Resolvers

`resolvers.js` (or similar name) will contain all the functions that resolve queries and mutations. These functions should be defined according to the schema you've defined.

For example, a simple resolver for `users` could look like this:

```javascript
const db = {};  // A simple in-memory database example
db.users = [
    { id: "1", name: "Alice", email: "alice@example.com" },
    { id: "2", name: "Bob", email: "bob@example.com" }
];

function usersResolver(db) {
    return function (root, args, context, info) {
        const { query } = info;

        if (!db.users.length || !query.name) {
            return db.users;
        }

        // Query all users or filter by name
        let result = db.users.filter(user => user.name.toLowerCase().includes(query.name.toLowerCase()));
        console.log(`Returning ${result.length} of 10 matching users.`);

        return result.slice(0, 10);
    };
}

module.exports = { usersResolver };

// This resolver will be called for queries that do not match the schema
const resolvers = {
    QueryType: {
        hello: (root, args) => `Hello ${args.name}!`,
        users: usersResolver(db),
    },
};
```

### Step 6: Start Your Server

Now you can start your server by running:

```bash
node server.js
```

At this point, your GraphQL server is up and running. You can test it using a tool like GraphiQL (a browser extension or standalone tool) which allows you to enter queries directly in the URL.

### Step 7: Add Authentication

You might want to add authentication mechanisms such as JWT for security. This would typically involve configuring your Express instance with an authenticator middleware and adding user management code.

```javascript
const { json } = require('body-parser');
const session = require('express-session');

app.use(session({
    secret: 'your-secret-key',
    resave: false,
    saveUninitialized: true
}));

app.post('/login', (req, res) => {
    // Logic to handle login request and authenticate the user.
});

// Add similar middleware for logout, registration etc.

// Serve GraphQL in Express using apollo-server-express
const { ApolloServer } = require('apollo-server-express');
const schema = require('./schema.graphql');

const server = new ApolloServer({
    typeDefs,
    resolvers: {
        QueryType: resolvers,
        MutationType: {
            createUser: (parent, args) => {
                // Add logic to save user in your database.
                return db.users.push(args.input);
            }
        },
        SubscriptionType: {
            // Your subscription resolver here
        }
    }
});

server.applyMiddleware({ app });
```

### Step 8: Connect to a Database

If you're using a database like MongoDB, you'll need to connect it within your schema and resolvers.

```javascript
const mongoose = require('mongoose');

// Use environment variables to connect with the database. This is for in-memory example.
process.env.MONGODB_URI || 'mongodb://localhost:27017/myDB';

mongoose.connect(process.env.MONGODB_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
});

const db = mongoose.connection;

db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', () => {
    console.log('Connected to MongoDB');
});
```

### Final Notes

This is a basic example. You can expand the server by adding more complex queries and mutations, using different databases (like MySQL or PostgreSQL), implementing authentication mechanisms (like JWT or OAuth2), and more.

Remember that GraphQL is all about having fewer requests, so make sure your resolvers are optimized to handle large datasets efficiently.

