```go
package main

import (
    "fmt"
    "net/http"
)

func main() {
    data := map[string]string{
        "key": "value",
    }

    url := fmt.Sprintf("http://localhost:8000/endpoint")
    body, err := json.Marshal(data)
    if err != nil {
        panic(err)
    }

