        for attribute in attributes {
            print("Attribute: \(attribute.key) -> \(attribute.value)")
        }

        let content = try! reader.text()
        print("Content: \(content)")
    }

    if tagName == name { // Replace with your actual tag name
        var childTags: [String] = []

        while !reader.isEndElement() {
            let childName = try! reader.name()

            if childName == "tag_name" { // Replace with your actual tag name
                childTags.append(childName)
            }

            if tagName != nil && childTagNames.isEmpty {
                print("No more content for \(tagName!)")
                break
            } else {
                tagName = childName
            }
        }

        if !childTags.isEmpty {
            print("Child Tags: \(childTags)")
        }
    }

    reader.next()
}
```

### 5. Handle End Elements

When you encounter an `EndElement`, update the current tag name to nil and check for more content.

```swift
if tagName == "tag_name" { // Replace with your actual tag name
    let endElement = try! reader.name()

    if endElement == "end_tag" { // Replace with your actual end tag name
        print("End of \(tagName!)")

        tagName = nil
    } else {
        print("\(endElement) is not the expected end tag. Skipping.")
    }
}
```

### 6. Clean Up

When you're done reading, make sure to release any resources:

```swift
try! reader.close()
```

### Example with an Actual XML String

Here's a concrete example for parsing an XML string:

```swift
